package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.json.*;
public class CacheSnapshotTest {
 @Test public void scheduledSaveKeepsSubmissionStateAfterCardAndListChanges()throws Exception{Library.Card card=new Library.Card("/fixture/original.mkv","Original",true);card.id=42;card.episodeRoots.add("/fixture/season-one");card.memberPaths.add("/fixture/first.mkv");List<Library.Card> cards=new ArrayList<>(List.of(card));List<Runnable> pending=new ArrayList<>();Path file=Files.createTempFile("cache-snapshot-", ".json");try{byte[] snapshot=CacheIo.snapshot(cards);java.util.concurrent.Executor injected=pending::add;injected.execute(()->{try{Files.write(file,snapshot);}catch(java.io.IOException e){throw new RuntimeException(e);}});card.title="Later";card.id=99;card.episodeRoots.clear();card.memberPaths.add("/fixture/second.mkv");cards.clear();pending.remove(0).run();JSONArray saved=new JSONArray(new String(Files.readAllBytes(file),StandardCharsets.UTF_8));assertEquals(1,saved.length());JSONObject record=saved.getJSONObject(0);assertEquals("Original",record.getString("title"));assertEquals(42,record.getLong("id"));assertEquals("/fixture/season-one",record.getJSONArray("episode_roots").getString(0));assertEquals(1,record.getJSONArray("members").length());assertEquals("Later",card.title);assertEquals(2,card.memberPaths.size());}finally{Files.deleteIfExists(file);}}
 @Test public void fiveThousandCardsSerializeDeterministicallyWithoutMutation()throws Exception{List<Library.Card> cards=new ArrayList<>();List<JSONObject> before=new ArrayList<>();List<Library.Card> originals=new ArrayList<>();for(int i=0;i<5000;i++){Library.Card card=new Library.Card("/fixture/"+i+".mkv","Title "+i,i%2==0);card.id=i;card.rating=(i%10)/2.0;card.overview="Overview "+i;card.episodeRoots.add("/fixture/season-"+i);card.memberPaths.add(card.path);cards.add(card);originals.add(card);before.add(card.json());}byte[] first=CacheIo.snapshot(cards),second=CacheIo.snapshot(cards);assertArrayEquals(first,second);JSONArray saved=new JSONArray(new String(first,StandardCharsets.UTF_8));assertEquals(5000,saved.length());for(int i=0;i<5000;i++){assertSame(originals.get(i),cards.get(i));assertEquals("Card changed at "+i,before.get(i).toString(),cards.get(i).json().toString());assertEquals("Snapshot differs at "+i,before.get(i).toString(),saved.getJSONObject(i).toString());}}
}
